-- ForzaInfinity schema, part 1 of 5: roles and shared trigger functions (ADR 0004).
--
-- Migrations are SQL-first and forward-only once production holds data (SER-M6 cutover); sqlx
-- records each file's checksum, so editing an applied migration fails the next `fi-worker
-- migrate` instead of drifting silently. Every timestamp is timestamptz in UTC; every id is a
-- UUIDv7 (PostgreSQL 18's uuidv7(), or generated by the service).
--
-- Group roles, NOLOGIN (logins are created by `fi-worker migrate` from Secret Manager passwords,
-- or by infra/docker/postgres/initdb locally, and granted these groups):
--   fi_runtime      the Cloud Run services (fi-api deployments, fi-progression-ingest): read and
--                   write rows, never delete, never DDL.
--   fi_maintenance  the jobs that prune (retention, outbox prune, erasure): the only DELETE grants.
-- The migrator login owns every object.

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fi_runtime') THEN
    CREATE ROLE fi_runtime NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fi_maintenance') THEN
    CREATE ROLE fi_maintenance NOLOGIN;
  END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO fi_runtime, fi_maintenance;

-- sqlx creates _sqlx_migrations before the first migration runs. Services read it so a revision
-- whose image expects a newer schema fails readiness instead of serving (fi_db::migrate::check_applied).
GRANT SELECT ON _sqlx_migrations TO fi_runtime, fi_maintenance;

-- Keeps updated_at and row_version honest on every mutable table: application code never sets
-- them, so a write that forgot to bump the version cannot exist.
CREATE FUNCTION fi_touch_row() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := clock_timestamp();
  NEW.row_version := OLD.row_version + 1;
  RETURN NEW;
END
$$;

-- Append-only tables refuse UPDATE outright.
CREATE FUNCTION fi_forbid_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE = 'restrict_violation';
END
$$;
